"""Fixtures for the W1-07 acceptance tests."""

from __future__ import annotations

import os
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent))

import w1_07_support as support  # noqa: E402


def pytest_configure(config):
    config.addinivalue_line("markers", "local_only: needs the dev tiers on this machine (GOV_DEV_TIERS); not for CI")


@pytest.fixture(scope="session")
def cli(tmp_path_factory):
    """The ``gov`` command, run from a temporary copy of ``src/`` through the script ``pyproject.toml`` declares."""
    try:
        return support.build_cli(tmp_path_factory.mktemp("w1-07-cli"))
    except support.CliMissing as exc:
        pytest.fail(f"the gov command does not exist: {exc}", pytrace=False)


@pytest.fixture()
def sandbox(tmp_path):
    """HOME and TMPDIR of one test, outside the project."""
    return support.make_sandbox(tmp_path / "sandbox")


@pytest.fixture(scope="session")
def shared_project(cli, tmp_path_factory):
    """A committed copy of the working tree, shared by the tests that expect no command to change it."""
    return support.copy_working_tree(tmp_path_factory.mktemp("w1-07-project") / "repo")


@pytest.fixture()
def project(shared_project):
    """The shared copy, checked clean before the test uses it."""
    status = support.git(shared_project, "status", "--porcelain", "--ignored")
    assert status == "", f"an earlier command left the shared project changed:\n{status}"
    return shared_project


@pytest.fixture()
def own_project(cli, tmp_path):
    """A committed copy of the working tree for one test that changes it."""
    return support.copy_working_tree(tmp_path / "repo")


@pytest.fixture()
def gov(cli, sandbox):
    """``gov(project, *argv, session=None, role=None)`` -- one command with ``--json --root <project>``."""

    def _gov(project, *argv, session=None, role=None):
        return support.run_command(cli, sandbox, project, *argv, session=session, role=role)

    return _gov


@pytest.fixture()
def raw_gov(cli, sandbox, tmp_path):
    """``raw_gov(*argv)`` -- ``gov`` with exactly these arguments, in an empty temporary directory."""
    cwd = tmp_path / "empty"
    cwd.mkdir()

    def _raw(*argv):
        return support.run_gov(cli, sandbox, cwd, *argv)

    return _raw


@pytest.fixture(scope="session")
def dev_tiers():
    """The directory of the synthetic dev tiers."""
    base = Path(os.environ.get("GOV_DEV_TIERS") or Path.home() / "gov-os-workbench" / "synthetic").expanduser()
    if not base.is_dir():
        pytest.skip(f"the dev tiers are not on this machine ({base})")
    return base

